const form=document.querySelector('#login-form');const error=document.querySelector('#error');const button=document.querySelector('#submit');form.addEventListener('submit',async event=>{event.preventDefault();error.textContent='';button.disabled=true;try{const response=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',cache:'no-store',body:JSON.stringify({username:form.elements.namedItem('username').value.trim(),password:form.elements.namedItem('password').value})});if(!response.ok){error.textContent=response.status===429?'Zu viele Versuche. Bitte später erneut versuchen.':'Anmeldung fehlgeschlagen.';return;}location.assign('/');}catch{error.textContent='Der Server ist derzeit nicht erreichbar.'}finally{button.disabled=false}});
